<?php

declare(strict_types=1);

namespace App\Repository;

use Doctrine\ORM\EntityRepository;
use Doctrine\ORM\NoResultException;

/**
 * ReservationRepository.
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 *
 * @extends EntityRepository<\App\Entity\Template>
 */
class TemplateRepository extends EntityRepository
{
    public function findAll(): array
    {
        return $this
            ->createQueryBuilder('t')
            ->select('t', 'tt')
            ->leftJoin('t.templateType', 'tt')
            ->addOrderBy('tt.name', \SortDirection::Ascending)
            ->addOrderBy('t.name', \SortDirection::Ascending)
            ->getQuery()
            ->getResult();
    }

    /**
     * @param list<string> $names Type-name LIKE patterns; empty keeps all visible templates with an assigned type
     *
     * @return list<\App\Entity\Template>|null Matching templates, or null on NoResultException
     */
    public function loadByTypeName($names)
    {
        $q = $this
            ->createQueryBuilder('t')
            ->select('t', 'tt')
            ->join('t.templateType', 'tt')
            ->addOrderBy('t.name', \SortDirection::Ascending);

        $len = count($names);
        for ($i = 0; $i < $len; ++$i) {
            if (0 == $i) {
                $q->where('tt.name LIKE :name'.$i.' ');
            } else {
                $q->orWhere('tt.name LIKE :name'.$i.' ');
            }
            $q->setParameter('name'.$i, $names[$i]);
        }

        // Präfix-Filter
        $q->andWhere('t.hidden = false');

        $templates = null;
        try {
            $templates = $q->getQuery()->getResult();
        } catch (NoResultException $e) {
        }

        return $templates;
    }
}
